"use client";

import { cn } from "@/lib/utils";
import { useToc, type TocHeading } from "@/hooks/use-toc";

export type { TocHeading } from "@/hooks/use-toc";

export type TocProps = {
  headings: TocHeading[];
  /** Heading shown above the list. Defaults to "on this page". */
  label?: string;
  className?: string;
};

/**
 * Sticky table-of-contents with scroll-spy highlighting. Give it the page's
 * headings ({ id, text }); the active row tracks scroll position via the
 * headless useToc hook. Sticks below a --sticky-header-offset CSS var.
 */
export function Toc({ headings, label = "on this page", className }: TocProps) {
  const activeId = useToc(headings);
  if (headings.length === 0) return null;

  return (
    <nav
      className={cn("sticky overflow-y-auto", className)}
      style={{
        top: "var(--sticky-header-offset, 80px)",
        maxHeight: "calc(100vh - var(--sticky-header-offset, 80px) - 2rem)",
      }}
    >
      <p className="mb-3 font-mono text-xs uppercase tracking-widest text-white/40">
        {label}
      </p>
      <ul className="space-y-0.5">
        {headings.map((h) => (
          <li key={h.id}>
            <a
              href={`#${h.id}`}
              aria-current={activeId === h.id ? "page" : undefined}
              className={cn(
                "block py-1 text-sm leading-5 transition-colors",
                activeId === h.id ? "text-white" : "text-white/50 hover:text-white",
              )}
            >
              {h.text}
            </a>
          </li>
        ))}
      </ul>
    </nav>
  );
}

"use client";

import { useEffect, useState } from "react";

export type TocHeading = {
  id: string;
  text: string;
};

/**
 * Headless scroll-spy: observes the elements whose ids are given and returns
 * the id of the one currently in view. No styling. The rootMargin keeps a
 * heading "active" until it scrolls into the top ~30% of the viewport.
 */
export function useToc(headings: TocHeading[], rootMargin = "-80px 0px -70% 0px"): string {
  const [activeId, setActiveId] = useState("");

  // Stable key over the heading ids so a fresh array literal with the same ids
  // doesn't re-subscribe the observer on every render.
  const idsKey = headings.map((h) => h.id).join("|");

  useEffect(() => {
    const ids = idsKey ? idsKey.split("|") : [];
    if (ids.length === 0) return;

    // Track which observed headings are currently intersecting; on every batch
    // pick the topmost intersecting one (in document order) so the result is
    // deterministic rather than "last entry in the batch wins".
    const intersecting = new Set<string>();

    const observer = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (entry.isIntersecting) intersecting.add(entry.target.id);
          else intersecting.delete(entry.target.id);
        }
        const topmost = ids.find((id) => intersecting.has(id));
        if (topmost) {
          setActiveId(topmost);
        } else {
          // Nothing intersecting: keep the last heading scrolled above the
          // viewport active, falling back to the first heading at the top.
          const passed = ids.filter((id) => {
            const el = document.getElementById(id);
            return el ? el.getBoundingClientRect().top < 0 : false;
          });
          setActiveId(passed[passed.length - 1] ?? ids[0] ?? "");
        }
      },
      { rootMargin },
    );
    for (const id of ids) {
      const el = document.getElementById(id);
      if (el) observer.observe(el);
    }
    return () => observer.disconnect();
  }, [idsKey, rootMargin]);

  return activeId;
}
